mapper.select:
/* SelectCommonCodeList commoncode-mapper.xml */ SELECT grp_cmm_cd /* 그룹공통코드 VARCHAR(100) */ , cd_vl /* 코드값 VARCHAR(100) */ , cd_vl_nm /* 코드값명 VARCHAR(150) */ , use_yn /* 사용여부 VARCHAR(2) */ , sort_no /* 정렬순서 BIGINT */ , in_emp_cd /* 입력자 VARCHAR(20) */ , in_dtm /* 입력일시 DATETIME */ , up_emp_cd /* 수정자 VARCHAR(20) */ , up_dtm /* 수정일시 DATETIME */ FROM tbcm_common_code WHERE mb_id = #{mb_id}
AND use_yn = #{use_yn}
AND UPPER(cd_vl) IN UPPER(#{item})
AND UPPER(grp_cmm_cd) = UPPER(#{grp_cmm_cd})
AND UPPER(grp_cmm_cd) IN UPPER(#{item})
AND SUBSTRING(cd_vl,1,1) = #{con}
AND cd_vl != #{search_word}
ORDER BY sort_no

/* commoncode-mapper.xml id="selectCommonCodeGroupList" 공통코드 그룹 리스트 조회 */ SELECT mb_id /* 회사코드 varchar(20)*/ , grp_cmm_cd /* 그룹공통코드 varchar(100)*/ , grp_cmm_cd_nm /* 그룹공통코드명 varchar(150)*/ , grp_cmm_cd_desc /* 그룹공통코드명 varchar(300)*/ , system_gubun /* 시스템 구분 varchar(10)*/ , sort_no /* 정렬순서 bigint(20)*/ FROM tbcm_common_code_group WHERE mb_id = #{mb_id}
AND (UPPER(grp_cmm_cd) LIKE CONCAT('%',UPPER(#{search_word}),'%') OR UPPER(grp_cmm_cd_nm) LIKE CONCAT('%',UPPER(#{search_word}),'%'))
ORDER BY sort_no DESC

mapper.update:
/* commoncode-mapper.xml id="updateCommonCodeValue" 공통 코드 수정(cd_vl 수정가능) */
UPDATE tbcm_common_code
  SET up_emp_cd = #{up_emp_cd}
  	, up_dtm = NOW()

  	, cd_vl = #{cd_vl}


  	, cd_vl_nm = #{cd_vl_nm}


  	, use_yn = #{use_yn}


  	, sort_no = #{sort_no}

 WHERE mb_id = #{mb_id}
   AND grp_cmm_cd = #{grp_cmm_cd}

mapper.insert:

	SELECT IFNULL(MAX(sort_no), 0) + 10 AS sort_no FROM tbcm_common_code_group WHERE mb_id = #{mb_id}


/* commoncode-mapper.xml id="insertCommonCodeGroup" 공통코드 그룹 입력 */
INSERT
  INTO tbcm_common_code_group
  	 ( mb_id             /* 회사코드 varchar(20)*/
	 , grp_cmm_cd        /* 그룹공통코드 varchar(100)*/
	 , grp_cmm_cd_nm     /* 그룹공통코드명 varchar(150)*/
	 , grp_cmm_cd_desc   /* 그룹공통코드명 varchar(300)*/
	 , system_gubun      /* 시스템 구분 varchar(10)*/
	 , sort_no           /* 정렬순서 bigint(20)*/
	 , in_emp_cd         /* 입력자사번 varchar(20)*/
	 , in_dtm            /* 입력일시 datetime*/
  	 )
VALUES
	 ( #{mb_id}
	 , UPPER(#{grp_cmm_cd})
	 , #{grp_cmm_cd_nm}
	 , #{grp_cmm_cd_desc}
	 , #{system_gubun}
	 , #{sort_no}
	 , #{in_emp_cd}
	 , NOW()
	 )

