mapper.select:
/* selectCommonCodeView commoncode-mapper.xml */ SELECT grp_cmm_cd /* 그룹공통코드 VARCHAR(100) */ , cd_vl /* 코드값 VARCHAR(100) */ , cd_vl_nm /* 코드값명 VARCHAR(150) */ , use_yn /* 사용여부 VARCHAR(2) */ , sort_no /* 정렬순서 BIGINT */ , in_emp_cd /* 입력자 VARCHAR(20) */ , in_dtm /* 입력일시 DATETIME */ , up_emp_cd /* 수정자 VARCHAR(20) */ , up_dtm /* 수정일시 DATETIME */ FROM tbcm_common_code WHERE mb_id = #{mb_id}
AND use_yn = #{use_yn}
AND UPPER(cd_vl) = UPPER(#{cd_vl})
AND UPPER(grp_cmm_cd) = UPPER(#{grp_cmm_cd})
LIMIT 0, 1
